import{_ as o,l as i,o as e,c as s,v as n,p as l,x as r,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"von Neumann EDVAC 报告","description":"","frontmatter":{"title":"von Neumann EDVAC 报告","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/von-neumann-edvac.md","filePath":"cs/von-neumann-edvac.md","lastUpdated":1789023840000}'),h={name:"cs/von-neumann-edvac.md"};function E(m,a,u,A,f,_){const t=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=n('<h1 id="von-neumann-edvac-报告" tabindex="-1">von Neumann EDVAC 报告 <a class="header-anchor" href="#von-neumann-edvac-报告" aria-label="Permalink to &quot;von Neumann EDVAC 报告&quot;">​</a></h1><div class="epigraph"><p>指令与数据放进同一存储器，控制按地址取指；机器的结构从此可以按字来谈，而不必为每种题目焊一套网。</p><footer>—— von Neumann, First Draft of a Report on the EDVAC, 1945</footer></div><p><a href="/cs/turing-1936-paper">上一课</a>附录对照了纸带上的可计算。附录对照，不插入主干。主干已在<a href="/cs/turing-1936-paper">存储程序</a>、<a href="/cs/instruction-format">指令格式</a>里用过「程序在内存里、PC 取指」；这里对照 <strong>1945 年 First Draft 的问题</strong>：电子数值装置如何组织成存储器、运算器与控制，使题目改写只需改存储内容。不重画单周期数据通路。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Turing 机有带，没有工程上的字宽、延迟与指令计数。ENIAC 一类装置大量用插线改题目。First Draft 的缺口是：用延迟线或同类存储同时放下数与指令，控制是对地址的中央逻辑。这不是可计算性新定理，是把通用机收成可建造的结构图。</p><p><span class="marginnote">报告是草稿，署名与团队贡献后来有争议。主干只取结构：存储程序、顺序控制。不把「冯·诺依曼瓶颈」的后世名称写进 1945 年原文没有的章节。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>报告分层：元件、存储器层次、算术、控制。指令是存储里的字，运算器对字做算术，控制解释操作码。主干<a href="/cs/single-cycle-datapath">单周期数据通路</a>已经把取指–译码–执行画成电路课；附录只对照草稿把这三件事写成同一份备忘录。</p>',8)),(e(),l(p,null,{default:r(()=>[c(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20MEM%5B%22%E5%AD%98%E5%82%A8%E5%99%A8%3A%20%E6%95%B0%E4%B8%8E%E6%8C%87%E4%BB%A4%22%5D%20--%3E%20CTRL%5B%22%E6%8E%A7%E5%88%B6%3A%20%E5%8F%96%E6%8C%87%22%5D%0A%20%20CTRL%20--%3E%20ALU%5B%22%E8%BF%90%E7%AE%97%E5%99%A8%22%5D%0A%20%20MEM%20--%3E%20ALU%0A%20%20CTRL%20--%3E%20TRUNK%5B%22%E4%B8%BB%E5%B9%B2%3A%20%E5%AD%98%E5%82%A8%E7%A8%8B%E5%BA%8F%E8%AF%BE%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=n('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>同一存储使编译与加载成为可能：后文<a href="/cs/link-reloc">链接与重定位</a>假设映像是字的数组。瓶颈（指令与数据争带宽）是后来体系结构课的对照，不是草稿的自我批评。本附录不把流水线、Cache 算进 1945。</p><h3 id="为何对照而不插入主干" tabindex="-1">为何对照而不插入主干 <a class="header-anchor" href="#为何对照而不插入主干" aria-label="Permalink to &quot;为何对照而不插入主干&quot;">​</a></h3><p>主干组成课从门与触发器走到存储程序，路径是电路。把 EDVAC 草稿插在 CMOS 之前，会让读者以为先有报告才有反相器。附录只对照原文如何命名中央控制与存储，以及主干已经取走的取指循环。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把报告写成第一台计算机的产权证明。也不要与 Turing 1936 抢「谁发明了计算机」。下一篇对照 Shannon 1948 如何把通信收成比特与噪声，那是本栏第一课的文献，不是组成课的下一章。</p><p>草稿里的串行控制与后来的中断、DMA 并存，主干 I/O 课已分开讲；不要把 1945 年备忘录读成已经包含总线仲裁。</p><p>对照结束应回到主干<a href="/cs/stored-program">存储程序</a>。草稿的元件层不是本栏 CMOS 课的替代。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>附录对照 EDVAC First Draft 1945：存储程序的工程草案。</li><li>主干存储程序与指令格式课已用该结构。</li><li>不插入门电路课序；不把后世瓶颈论写回草稿。</li><li>出处：von Neumann, <em>First Draft of a Report on the EDVAC</em>, 1945。</li></ul>',10))])}const D=o(h,[["render",E]]);export{C as __pageData,D as default};
